def options(text, formal=False):
    toks, pairs = _audited_options(text, formal)
    checked=[]
    for i,m,v in pairs:
        prefix=text[:m.start()]
        article=re.search(r'\b(a|an)\s+$',prefix,re.I)
        if article and ((article.group(1).lower()=='an') != (v[0].lower() in 'aeiou')):
            continue
        if m.group().lower()=='no' and re.search(r'\b(is|are|can|could|has|have|was|were)\b',text,re.I):
            continue
        checked.append((i,m,v))
    return toks,checked
